<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {login} from '@/api';const f=reactive({username:'admin',password:'123456'}),loading=ref(false),router=useRouter();async function submit(){loading.value=true;try{const d:any=await login(f.username,f.password);localStorage.token=d.token;router.push('/')}finally{loading.value=false}}</script>
<template><main class="login"><section><b>QA</b><p>TEST CASE WORKBENCH</p><h1>用例管理平台</h1><span>把测试想法变成清晰、可追踪的用例。</span><el-form @submit.prevent="submit"><el-input v-model="f.username" size="large" placeholder="用户名"/><el-input v-model="f.password" type="password" show-password size="large" placeholder="密码"/><el-button type="primary" native-type="submit" size="large" :loading="loading">登录工作台</el-button></el-form><small>演示账号：admin / 123456</small></section></main></template>
